import type { StorybookConfig } from "@storybook/react-vite";
import {
	uiFramework,
	uiStories,
	withUiVite,
} from "../../ui/.storybook/shared.ts";

const config: StorybookConfig = {
	stories: [
		uiStories,
		"../../web-client/src/**/*.stories.@(ts|tsx)",
		"../src/**/*.stories.@(ts|tsx)",
	],
	addons: ["@storybook/addon-vitest"],
	framework: uiFramework,
	// Serves the MSW service worker generated by `npm run msw:init`, and the
	// web client's locales, which its i18n fetches over HTTP.
	staticDirs: ["../public", "../../web-client/public"],
	core: { disableTelemetry: true },
	async viteFinal(config) {
		const { spellcheckPlugin } = await import(
			"../../web-client/spellcheck/vite-plugin.ts"
		);
		const { fileURLToPath, URL } = await import("node:url");
		const withUi = await withUiVite(config);
		// The spellcheck stories drive the real worker, which fetches the engine
		// and the dictionaries the same way the app does.
		withUi.plugins.push(spellcheckPlugin());
		withUi.resolve.alias = {
			...withUi.resolve.alias,
			// web-client stories (e.g. ConfirmDialog) use its own "@/" alias for
			// in-package imports — mirrors `webClientAlias()` in
			// packages/web-client/vite.base.ts, which Storybook doesn't load.
			"@": fileURLToPath(new URL("../../web-client/src", import.meta.url)),
		};
		return withUi;
	},
};

export default config;
